import"./chunk-VC46IEJQ.js";var e=(t,n,o,d,l,s,r,h,a)=>({name:{en:t[0],zh:t[1]},desc:{en:n[0],zh:n[1]},tour:{en:o[0],zh:o[1]},...a?{spoiler:{en:a[0],zh:a[1]}}:{},source:{confidence:d,refs:l,book:{en:s[0],zh:s[1]},unknown:{en:r[0],zh:r[1]},interpretation:{en:h[0],zh:h[1]}}}),i={id:"hardhome",intro:{en:"A sheltered harbour on the coast far beyond the Wall, once the closest thing to a town the free folk ever had. Six centuries ago it burned in a single night, and men have shunned it since. The books describe it only briefly, so this scene is deliberately sparse.",zh:"\u957F\u57CE\u4EE5\u5317\u8FDC\u65B9\u6D77\u5CB8\u4E0A\u7684\u4E00\u5904\u907F\u98CE\u6E2F\uFF0C\u66FE\u662F\u81EA\u7531\u6C11\u6240\u62E5\u6709\u7684\u6700\u63A5\u8FD1\u57CE\u9547\u7684\u5730\u65B9\u3002\u516D\u767E\u5E74\u524D\uFF0C\u5B83\u5728\u4E00\u591C\u4E4B\u95F4\u711A\u6BC1\uFF0C\u6B64\u540E\u4EBA\u8FF9\u7F55\u81F3\u3002\u4E66\u4E2D\u7740\u58A8\u4E0D\u591A\uFF0C\u672C\u573A\u666F\u56E0\u6B64\u523B\u610F\u4ECE\u7B80\u3002"},notes:{en:"From the novels: a natural harbour deep enough for large ships, a settlement under a cliff riddled with caves, destroyed by fire six hundred years ago and long thought cursed. Everything else (palisade, hall, hulls, grove, jetty) is interpretation to give the place a shape, not canon.",zh:"\u51FA\u81EA\u5C0F\u8BF4\uFF1A\u4E00\u5904\u53EF\u6CCA\u5927\u8239\u7684\u5929\u7136\u826F\u6E2F\uFF0C\u805A\u843D\u80CC\u9760\u6D1E\u7A74\u5BC6\u5E03\u7684\u60AC\u5D16\uFF0C\u516D\u767E\u5E74\u524D\u6BC1\u4E8E\u5927\u706B\uFF0C\u6B64\u540E\u957F\u671F\u88AB\u89C6\u4E3A\u4E0D\u7965\u4E4B\u5730\u3002\u5176\u4F59\u4E00\u5207\uFF08\u6728\u6805\u3001\u5385\u5802\u3001\u8239\u9AB8\u3001\u6811\u6797\u3001\u6808\u6865\uFF09\u90FD\u662F\u4E3A\u4F7F\u6B64\u5730\u6210\u5F62\u800C\u4F5C\u7684\u89E3\u8BFB\uFF0C\u5E76\u975E\u539F\u8457\u8BBE\u5B9A\u3002"},tour:["harbour-bay","old-jetty","hulls-on-the-shore","palisade","ruined-hall","weirwood-grove","headland-cliffs"],sources:[{ref:"acok",checked:"memory",note:{en:"Jon recalls the tale of Hardhome's burning; recalled in outline only.",zh:"\u743C\u6069\u56DE\u60F3\u8D77\u8270\u96BE\u5C6F\u711A\u6BC1\u7684\u4F20\u8BF4\uFF1B\u4EC5\u51ED\u8BB0\u5FC6\u8BB0\u5F97\u6897\u6982\u3002"}},{ref:"adwd",checked:"memory",note:{en:"Hardhome becomes a refuge for free folk and the goal of a rescue by sea; recalled in outline, not re-read.",zh:"\u8270\u96BE\u5C6F\u6210\u4E3A\u81EA\u7531\u6C11\u7684\u907F\u96BE\u6240\uFF0C\u4E5F\u662F\u4E00\u6B21\u6D77\u4E0A\u6551\u63F4\u7684\u76EE\u7684\u5730\uFF1B\u4EC5\u51ED\u8BB0\u5FC6\u8BB0\u5F97\u6897\u6982\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"A search summary of the wiki describes the town under a tall cliff full of caves, a sheltered bay deep enough for large ships, and the burning six centuries ago. The page was not fetched.",zh:"\u7EF4\u57FA\u7684\u641C\u7D22\u6458\u8981\u63D0\u5230\uFF1A\u805A\u843D\u80CC\u9760\u4E00\u9762\u6D1E\u7A74\u5BC6\u5E03\u7684\u9AD8\u5D16\uFF0C\u6D77\u6E7E\u907F\u98CE\u4E14\u6C34\u6DF1\u53EF\u6CCA\u5927\u8239\uFF0C\u4EE5\u53CA\u516D\u767E\u5E74\u524D\u7684\u5927\u706B\u3002\u9875\u9762\u672A\u6293\u53D6\u3002"}},{ref:"twoiaf",checked:"not-accessed",note:{en:"The companion's history of Hardhome was not checked.",zh:"\u672A\u67E5\u8BC1\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u4E2D\u5173\u4E8E\u8270\u96BE\u5C6F\u7684\u5386\u53F2\u3002"}}],landmarks:{"harbour-bay":e(["Harbour Bay","\u6D77\u6E7E"],["A sheltered bay on the cold coast, deep enough for large ships, with grey water and drifting ice.","\u5BD2\u51B7\u6D77\u5CB8\u4E0A\u7684\u907F\u98CE\u6D77\u6E7E\uFF0C\u6C34\u6DF1\u53EF\u6CCA\u5927\u8239\uFF0C\u6D77\u6C34\u7070\u6697\uFF0C\u6D6E\u51B0\u6F02\u8361\u3002"],["A sheltered bay, deep enough for ships, on a coast with few such places.","\u4E00\u5904\u6C34\u6DF1\u53EF\u6CCA\u5927\u8239\u7684\u907F\u98CE\u6D77\u6E7E\uFF0C\u5728\u8FD9\u7247\u6D77\u5CB8\u4E0A\u5B9E\u5C5E\u96BE\u5F97\u3002"],"medium",["acok","adwd","awoiaf"],["Hardhome lies on a natural harbour, sheltered and deep enough for large ships.","\u8270\u96BE\u5C6F\u5750\u843D\u5728\u4E00\u5904\u5929\u7136\u826F\u6E2F\u65C1\uFF0C\u6D77\u6E7E\u907F\u98CE\uFF0C\u6C34\u6DF1\u53EF\u6CCA\u5927\u8239\u3002"],["The bay's true shape and size.","\u6D77\u6E7E\u7684\u771F\u5B9E\u5F62\u72B6\u4E0E\u5927\u5C0F\u3002"],["The crescent shape and the ice floes are invented.","\u65B0\u6708\u5F62\u6D77\u6E7E\u4E0E\u6D6E\u51B0\u5747\u4E3A\u81EA\u62DF\u3002"],["In the fifth book ships of the Night's Watch sail here to rescue free folk, and fare badly in the storms.","\u7B2C\u4E94\u5377\u4E2D\uFF0C\u5B88\u591C\u4EBA\u7684\u8239\u53EA\u524D\u6765\u8425\u6551\u81EA\u7531\u6C11\uFF0C\u5374\u5728\u98CE\u66B4\u4E2D\u635F\u5931\u60E8\u91CD\u3002"]),"old-jetty":e(["Old Jetty","\u65E7\u6808\u6865"],["A broken timber jetty: black stumps and a few planks running out into the water.","\u4E00\u5EA7\u6B8B\u7834\u7684\u6728\u6808\u6865\uFF1A\u9ED1\u8272\u6728\u6869\u548C\u51E0\u5757\u6B8B\u677F\u4F38\u5165\u6C34\u4E2D\u3002"],["A jetty of black stumps runs out into the water.","\u4E00\u6392\u9ED1\u8272\u6B8B\u6869\u4F38\u5411\u6C34\u4E2D\uFF0C\u4FBF\u662F\u65E7\u6808\u6865\u3002"],"low",["adwd"],["A harbour implies landing places; no jetty is described.","\u65E2\u662F\u6E2F\u53E3\uFF0C\u603B\u8981\u6709\u767B\u5CB8\u4E4B\u5904\uFF1B\u4F46\u4E66\u4E2D\u672A\u63CF\u5199\u6808\u6865\u3002"],["Whether any jetty exists and what it looks like.","\u662F\u5426\u6709\u6808\u6865\u53CA\u5176\u6837\u8C8C\u3002"],["A stumpy jetty about thirty metres long is invented.","\u4E00\u5EA7\u7EA6\u4E09\u5341\u7C73\u957F\u7684\u6B8B\u6869\u6808\u6865\u4E3A\u81EA\u62DF\u3002"]),"hulls-on-the-shore":e(["Hulls on the Shore","\u5CB8\u4E0A\u8239\u9AB8"],["Ribs and keels of ships left on the shingle to rot.","\u5F03\u5728\u783E\u77F3\u6EE9\u4E0A\u8150\u673D\u7684\u8239\u808B\u4E0E\u9F99\u9AA8\u3002"],["Ships' ribs lie bleached on the shingle.","\u8239\u9AA8\u5728\u783E\u77F3\u6EE9\u4E0A\u6652\u5F97\u53D1\u767D\u3002"],"low",["adwd"],["Ships matter in Hardhome's story, but no wrecks on the beach are described.","\u8239\u53EA\u5728\u8270\u96BE\u5C6F\u7684\u6545\u4E8B\u4E2D\u4E3E\u8DB3\u8F7B\u91CD\uFF0C\u4F46\u4E66\u4E2D\u5E76\u672A\u63CF\u5199\u6D77\u6EE9\u4E0A\u7684\u8239\u9AB8\u3002"],["Whether any wrecks lie ashore.","\u5CB8\u4E0A\u662F\u5426\u6709\u8239\u9AB8\u3002"],["Three skeletal hulls are invented.","\u4E09\u5177\u9AA8\u67B6\u822C\u7684\u8239\u9AB8\u4E3A\u81EA\u62DF\u3002"]),palisade:e(["Palisade","\u6728\u6805"],["A gapped fence of leaning stakes around the settlement.","\u73AF\u7ED5\u805A\u843D\u7684\u4E00\u5708\u503E\u659C\u6728\u6869\uFF0C\u7F3A\u53E3\u7D2F\u7D2F\u3002"],["A gap-toothed palisade of leaning stakes.","\u4E1C\u5012\u897F\u6B6A\u3001\u7F3A\u53E3\u5904\u5904\u7684\u6728\u6805\u3002"],"low",["adwd"],["The books describe a burned, long-abandoned settlement; no defences are described.","\u4E66\u4E2D\u5199\u7684\u662F\u4E00\u5EA7\u711A\u6BC1\u540E\u4E45\u5DF2\u8352\u5E9F\u7684\u805A\u843D\uFF0C\u5E76\u672A\u63D0\u53CA\u9632\u5FA1\u5DE5\u4E8B\u3002"],["Whether there were any defences at all.","\u662F\u5426\u66FE\u6709\u4EFB\u4F55\u9632\u5FA1\u8BBE\u65BD\u3002"],["A broken arc of stakes is invented.","\u4E00\u9053\u65AD\u7EED\u7684\u5F27\u5F62\u6728\u6869\u4E3A\u81EA\u62DF\u3002"]),"ruined-hall":e(["Ruined Hall","\u5E9F\u5385"],["The skeleton of a longhall: stone footing, a standing gable and charred rafters.","\u4E00\u5EA7\u957F\u5385\u7684\u6B8B\u9AB8\uFF1A\u77F3\u780C\u5730\u57FA\u3001\u4E00\u9762\u5C1A\u5B58\u7684\u5C71\u5899\u4E0E\u7126\u9ED1\u7684\u693D\u6728\u3002"],["Blackened rafters under open sky recall the night Hardhome burned.","\u7126\u9ED1\u7684\u693D\u6728\u655E\u5BF9\u5929\u7A7A\uFF0C\u4EE4\u4EBA\u60F3\u8D77\u8270\u96BE\u5C6F\u711A\u6BC1\u7684\u90A3\u4E00\u591C\u3002"],"low",["acok","adwd"],["Hardhome burned so fiercely six hundred years ago that men on the Wall thought the sun was rising in the north; what caused it is disputed.","\u516D\u767E\u5E74\u524D\u8270\u96BE\u5C6F\u5927\u706B\u51B2\u5929\uFF0C\u957F\u57CE\u4E0A\u7684\u4EBA\u8FD8\u4EE5\u4E3A\u592A\u9633\u4ECE\u5317\u65B9\u5347\u8D77\uFF1B\u8D77\u706B\u539F\u56E0\u4F17\u8BF4\u7EB7\u7EAD\u3002"],["Whether a hall stood here, and what survives of the old town.","\u6B64\u5904\u662F\u5426\u6709\u8FC7\u5385\u5802\uFF0C\u65E7\u9547\u53C8\u6709\u4F55\u9057\u5B58\u3002"],["A single ruined longhall is invented.","\u4E00\u5EA7\u6B8B\u7834\u7684\u957F\u5385\u4E3A\u81EA\u62DF\u3002"]),"weirwood-grove":e(["Weirwood Grove","\u9C7C\u6881\u6728\u6797"],["A small stand of weirwoods on the slope behind the town, pale among dark pines.","\u9547\u540E\u5C71\u5761\u4E0A\u7684\u4E00\u5C0F\u7247\u9C7C\u6881\u6728\uFF0C\u5728\u58A8\u7EFF\u677E\u6797\u95F4\u663E\u5F97\u683C\u5916\u82CD\u767D\u3002"],["Pale weirwoods stand on the slope behind the town.","\u82CD\u767D\u7684\u9C7C\u6881\u6728\u9759\u7ACB\u5728\u9547\u540E\u7684\u5C71\u5761\u4E0A\u3002"],"low",["adwd"],["Weirwoods grow beyond the Wall, but none is described at Hardhome.","\u957F\u57CE\u4EE5\u5317\u751F\u957F\u7740\u9C7C\u6881\u6728\uFF0C\u4F46\u4E66\u4E2D\u5E76\u672A\u63D0\u5230\u8270\u96BE\u5C6F\u6709\u9C7C\u6881\u6728\u3002"],["Whether any weirwoods grow here.","\u6B64\u5730\u662F\u5426\u751F\u957F\u9C7C\u6881\u6728\u3002"],["Seven trees are placed purely for atmosphere.","\u4E03\u682A\u9C7C\u6881\u6728\u7EAF\u4E3A\u8425\u9020\u6C1B\u56F4\u800C\u8BBE\u3002"]),"headland-cliffs":e(["Cliffs and Caves","\u60AC\u5D16\u4E0E\u6D1E\u7A74"],["Dark, snow-streaked cliffs hem in the bay; caves riddle the cliff above the town.","\u6302\u7740\u96EA\u75D5\u7684\u6DF1\u8272\u60AC\u5D16\u73AF\u62B1\u6D77\u6E7E\uFF0C\u9547\u5B50\u4E0A\u65B9\u7684\u5D16\u58C1\u5E03\u6EE1\u6D1E\u7A74\u3002"],["Since the burning, the caves in the cliff are said to scream.","\u81EA\u90A3\u573A\u5927\u706B\u4E4B\u540E\uFF0C\u636E\u8BF4\u5D16\u4E0A\u7684\u6D1E\u7A74\u4F1A\u53D1\u51FA\u5C16\u53EB\u3002"],"medium",["adwd","awoiaf"],["The town lies under a tall cliff full of caves, the only shelter left standing; brothers of the Watch call them the screaming caves.","\u805A\u843D\u80CC\u9760\u4E00\u9762\u6D1E\u7A74\u5BC6\u5E03\u7684\u9AD8\u5D16\uFF0C\u90A3\u4E9B\u6D1E\u7A74\u662F\u5982\u4ECA\u4EC5\u5B58\u7684\u906E\u853D\u4E4B\u6240\uFF1B\u5B88\u591C\u4EBA\u79F0\u4E4B\u4E3A\u201C\u5C16\u53EB\u6D1E\u7A74\u201D\u3002"],["The true line of the coast and the cliffs.","\u6D77\u5CB8\u7EBF\u4E0E\u60AC\u5D16\u7684\u771F\u5B9E\u8D70\u5411\u3002"],["Two cliffed headlands framing the bay are invented; the caves are not modelled.","\u73AF\u62B1\u6D77\u6E7E\u7684\u4E24\u5EA7\u60AC\u5D16\u5CAC\u89D2\u4E3A\u81EA\u62DF\uFF1B\u6D1E\u7A74\u672A\u4F5C\u5EFA\u6A21\u3002"])}};export{i as default};
